// Pseudo: assumes 1-based for simplicity
for (let i=1; i<=n; i++) {
  for (let t=1; t<=k; t++) {
    let best = dp[i-1][t];
    for (let s=1; s<=i; s++) {
      best = Math.max(best, dp[s-2][t-1] + (pref[i]-pref[s-1]));
    }
    dp[i][t] = best;
  }
}
